def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    my_c = 0
    unprov = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
        if i > 0 and b == 'D' and history[i - 1][0] == 'C' and history[i - 1][1] == 'C':
            unprov += 1

    overall_opp = opp_c / float(n)

    recent_len = 12 if n >= 12 else n
    recent_opp = 0.5
    if recent_len > 0:
        cnt = 0
        start = n - recent_len
        for i in range(start, n):
            if history[i][1] == 'C':
                cnt += 1
        recent_opp = cnt / float(recent_len)

    last_my, last_opp = history[-1]

    def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_streak += 1
        else:
            break

    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            coop_streak += 1
        else:
            break

    my_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_def_streak += 1
        else:
            break

    c_total = 0
    c_coop = 0
    d_total = 0
    d_coop = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        opp_now = history[i][1]
        if prev_my == 'C':
            c_total += 1
            if opp_now == 'C':
                c_coop += 1
        else:
            d_total += 1
            if opp_now == 'C':
                d_coop += 1

    if c_total >= 3:
        p_c = c_coop / float(c_total)
    else:
        p_c = recent_opp

    if d_total >= 3:
        p_d = d_coop / float(d_total)
    elif d_total == 1:
        p_d = (d_coop + p_c) / 2.0
    elif d_total == 2:
        p_d = (d_coop + 1) / 3.0
    else:
        p_d = p_c

    rounds_left = 100 - n

    if opp_c == 0:
        return 'D'

    if def_streak == 3 and last_my == 'D' and rounds_left > 3:
        return 'C'

    if def_streak >= 4:
        if overall_opp <= 0.30 or recent_opp <= 0.25:
            return 'D'
        if last_my == 'C' and unprov >= 3 and overall_opp >= 0.50 and rounds_left > 5:
            return 'C'
        if p_d <= 0.35 and overall_opp >= 0.40:
            return 'C'
        if def_streak >= 7:
            return 'D'
        return 'D'

    if overall_opp <= 0.18 or recent_opp <= 0.18:
        return 'D'

    if n == 98:
        if last_opp == 'C' and d_total >= 2 and p_d <= 0.35 and p_c >= 0.80:
            return 'C'
        return 'D'

    probe_rounds = (25, 50, 75)

    if n in probe_rounds and opp_c == n and my_c == n and rounds_left > 15:
        return 'D'

    if (n - 1) in probe_rounds and last_my == 'D' and last_opp == 'C' and opp_c == n and my_c == n - 1:
        return 'C'

    if n >= 2 and history[-2][0] == 'D' and history[-1][0] == 'C' and history[-1][1] == 'C':
        if recent_opp >= 0.55 and overall_opp >= 0.45:
            return 'D'

    if (last_my == 'D' and last_opp == 'C' and recent_opp >= 0.55 and overall_opp >= 0.45 and
            (d_total >= 3 or p_d >= 0.45)):
        return 'D'

    if unprov >= 3 and overall_opp <= 0.75 and recent_opp >= 0.35 and n >= 15:
        return 'D'

    if last_opp == 'D':
        if def_streak == 1:
            if unprov >= 1 and overall_opp <= 0.82 and recent_opp >= 0.28:
                return 'D'
            if overall_opp >= 0.75 and recent_opp >= 0.62:
                return 'C'
            if p_c >= 0.50 and p_d >= 0.40:
                return 'C'
            return 'D'
        if def_streak == 2:
            if overall_opp >= 0.70 and recent_opp >= 0.55 and p_d <= 0.35:
                return 'C'
            return 'D'
        return 'D'

    if last_opp == 'C':
        if recent_opp < 0.38 or overall_opp < 0.40:
            return 'D'
        return 'C'

    return 'C'
